On the question posted by Willeke, here is an efficient way to do it :
// Guess "ends with s" of input string
function endsWith(s) {
    return s.charAt(s.length - 1) == 's';
}

// For each item a in arrayA, count how many items a is contained in arrayB
function countCommon(a, b) {
    return Array.prototype.some.call(b, b => a.some(v => v.endsWith(b)));
}
